html:
{% set company_currency = frappe.db.get_value("Company", doc.company, "default_currency") %}
{% set qr = get_doc_qr_code(doc.doctype, doc.name) %}

<style>
.cgm-doc {
	font-family: Inter, Arial, sans-serif;
	color: #171717;
	font-size: 12px;
	line-height: 1.45;
}
.cgm-doc h2 {
	margin: 0 0 14px;
	font-size: 20px;
	letter-spacing: 0.5px;
	text-transform: uppercase;
	color: #8b1a1a;
	text-align: center;
}
.cgm-doc h3 {
	margin: 0 0 8px;
	font-size: 13px;
	color: #8b1a1a;
	text-transform: uppercase;
}
.cgm-doc a {
	color: #171717;
	text-decoration: none;
}
.cgm-meta,
.cgm-kv {
	width: 100%;
	border-collapse: collapse;
	margin-bottom: 14px;
}
.cgm-meta td {
	vertical-align: top;
	padding: 4px 8px 4px 0;
	color: #171717;
}
.cgm-kv td {
	vertical-align: top;
	padding: 4px 8px 4px 0;
	color: #171717;
}
.cgm-label {
	color: #555;
	width: 150px;
	white-space: nowrap;
}

/* ── Shipment info band ── */
.cgm-info-band {
	width: 100%;
	border-collapse: collapse;
	margin: 0 0 16px;
	background: #f7f8fa;
	border: 1px solid #e2e4e9;
}
.cgm-info-band td {
	padding: 7px 12px;
	vertical-align: top;
	border-bottom: 1px solid #e2e4e9;
	font-size: 12px;
	color: #171717;
}
.cgm-info-band tr:last-child td {
	border-bottom: none;
}
.cgm-info-band .ib-label {
	color: #555;
	white-space: nowrap;
	width: 130px;
	font-weight: 500;
}
.cgm-info-band .ib-val {
	font-weight: 600;
	padding-right: 24px;
	color: #171717;
}
.cgm-info-band .ib-divider {
	border-left: 1px solid #e2e4e9;
	width: 1px;
	padding: 0;
}

.cgm-grid {
	width: 100%;
	border-collapse: collapse;
	margin: 12px 0;
}
.cgm-grid th {
	background: #8b1a1a;
	color: #fff;
	padding: 8px;
	text-align: left;
	font-size: 11px;
}
.cgm-grid td {
	border: 1px solid #e5e5e5;
	padding: 7px 8px;
	color: #171717;
}
.cgm-grid .num {
	text-align: right;
	white-space: nowrap;
}
.cgm-highlight {
	background: #fff8d6;
	font-weight: 600;
}
.cgm-totals {
	width: 100%;
	margin-top: 12px;
}
.cgm-totals td {
	padding: 5px 8px;
	color: #171717;
}
.cgm-totals .label {
	text-align: right;
	color: #555;
	width: 70%;
}
.cgm-totals .value {
	text-align: right;
	font-weight: 600;
	white-space: nowrap;
	color: #171717;
}
.cgm-totals tr:last-child .label,
.cgm-totals tr:last-child .value {
	color: #8b1a1a;
	font-size: 13px;
}
.cgm-terms {
	margin-top: 18px;
	padding: 12px;
	background: #fdf5f5;
	border: 1px solid #e8c8c8;
	color: #171717;
}
.cgm-terms strong {
	color: #8b1a1a;
}
.cgm-section {
	margin-top: 16px;
}
.cgm-qr {
	margin-top: 18px;
	text-align: center;
}
.cgm-qr img {
	width: 96px;
	height: 96px;
}
.cgm-qr .caption {
	margin-top: 6px;
	font-size: 10px;
	color: #555;
}
.text-right { text-align: right; }
.text-center { text-align: center; }
.letter-head { margin-bottom: 16px; }
.letter-head-footer { margin-top: 20px; }
</style>

<div class="cgm-doc">

{% if not no_letterhead and letter_head %}
<div class="letter-head">{{ letter_head }}</div>
{% endif %}

<!-- Header: TO/FROM block + Quotation meta -->
<table class="cgm-meta">
	<tr>
		<td style="width:55%">
			<strong>TO</strong><br>
			{{ doc.customer_name or doc.party_name or "" }}<br>
			{{ doc.address_display or "" }}

			<br><br>

			<strong>FROM</strong><br>
			CGM Worldwide Shipping Company Ltd<br>
			P.O. Box 5682-00100 Kiambu<br>
			The Oval Office Building, 7th Floor Westlands, Nairobi, Kenya.
		</td>
		<td class="text-right">
			<h2>Quotation</h2>
			<strong>Date:</strong> {{ frappe.utils.format_date(doc.transaction_date) }}<br>
			<strong>Valid Till:</strong>
			{% if doc.valid_till %}
				{{ frappe.utils.format_date(doc.valid_till) }}
			{% else %}
				-
			{% endif %}
			<br>
			<strong>Quotation No:</strong> {{ doc.name }}<br>
			{% if doc.custom_our_ref_no %}
			<strong>Our Ref:</strong> {{ doc.custom_our_ref_no }}<br>
			{% endif %}
			{% if doc.custom_client_ref_no %}
			<strong>Client Ref:</strong> {{ doc.custom_client_ref_no }}<br>
			{% endif %}
		</td>
	</tr>
</table>

<!-- Shipment details: unified info band -->
<table class="cgm-info-band">
	{% if doc.custom_shipment %}
	<tr>
		<td class="ib-label">Shipment / Project</td>
		<td class="ib-val">{{ doc.custom_shipment }}</td>
		<td class="ib-divider"></td>
		<td class="ib-label">HS Code</td>
		<td class="ib-val">{{ doc.custom_hs_code or "-" }}</td>
	</tr>
	{% endif %}
	{% if doc.custom_coo or doc.custom_commodity %}
	<tr>
		<td class="ib-label">Country of Origin</td>
		<td class="ib-val">{{ doc.custom_coo or "-" }}</td>
		<td class="ib-divider"></td>
		<td class="ib-label">Commodity</td>
		<td class="ib-val">{{ doc.custom_commodity or "-" }}</td>
	</tr>
	{% endif %}
	{% if doc.custom_idfno or doc.custom_weight %}
	<tr>
		<td class="ib-label">IDF No</td>
		<td class="ib-val">{{ doc.custom_idfno or "-" }}</td>
		<td class="ib-divider"></td>
		<td class="ib-label">Total Weight (Tons)</td>
		<td class="ib-val">{{ doc.custom_weight or "-" }}</td>
	</tr>
	{% endif %}
	{% if doc.incoterm or doc.custom_cargo_type or doc.custom_quantity %}
	<tr>
		<td class="ib-label">Incoterm</td>
		<td class="ib-val">
			{{ doc.incoterm or "-" }}
			{% if doc.named_place %}({{ doc.named_place }}){% endif %}
		</td>
		<td class="ib-divider"></td>
		<td class="ib-label">FCL</td>
		<td class="ib-val">
			{% if doc.custom_quantity %}{{ doc.custom_quantity }} x {% endif %}
			{{ doc.custom_cargo_type or "-" }}
			{% if doc.custom_shipment_type %}({{ doc.custom_shipment_type }}){% endif %}
		</td>
	</tr>
	{% endif %}
	{% if doc.custom_port_of_loading or doc.custom_port_of_discharge %}
	<tr>
		<td class="ib-label">Port of Loading</td>
		<td class="ib-val">{{ doc.custom_port_of_loading or "-" }}</td>
		<td class="ib-divider"></td>
		<td class="ib-label">Port of Discharge</td>
		<td class="ib-val">{{ doc.custom_port_of_discharge or "-" }}</td>
	</tr>
	{% endif %}
</table>

{% if doc.custom_import_cost_component %}
<div class="cgm-section">
	<h3>Valuation</h3>
	<table class="cgm-grid">
		<thead>
			<tr>
				<th>Description</th>
				<th class="num">{{ doc.currency }}</th>
				<th class="num">{{ company_currency }}</th>
			</tr>
		</thead>
		<tbody>
			{% for row in doc.custom_import_cost_component %}
			<tr>
				<td>{{ row.charge_item }}</td>
				<td class="num">{{ frappe.utils.fmt_money(row.amount or 0, currency=doc.currency) }}</td>
				<td class="num">{{ frappe.utils.fmt_money(row.amount_kes or 0, currency=company_currency) }}</td>
			</tr>
			{% endfor %}
			<tr class="cgm-highlight">
				<td><strong>Customs Value</strong></td>
				<td class="num">{{ doc.get_formatted("custom_custom_value") }}</td>
				<td class="num">{{ doc.get_formatted("custom_base_customs_value") }}</td>
			</tr>
		</tbody>
	</table>
</div>
{% endif %}

{% if doc.custom_customs_taxes %}
<div class="cgm-section">
	<h3>Taxes (Estimate)</h3>
	<table class="cgm-grid">
		<thead>
			<tr>
				<th>Tax Type</th>
				<th class="num">Tax Base ({{ company_currency }})</th>
				<th class="num">Rate</th>
				<th class="num">Amount ({{ company_currency }})</th>
			</tr>
		</thead>
		<tbody>
			{% for tax in doc.custom_customs_taxes %}
			<tr>
				<td>{{ tax.tax_type }}</td>
				<td class="num">{{ doc.get_formatted("custom_base_customs_value") }}</td>
				<td class="num">
					{% if tax.rate %}
					{{ tax.rate }}%
					{% elif tax.fixed_amount_kes %}
					{{ frappe.utils.fmt_money(tax.fixed_amount_kes, currency=company_currency) }}
					{% else %}
					-
					{% endif %}
				</td>
				<td class="num">{{ frappe.utils.fmt_money(tax.amount_kes or 0, currency=company_currency) }}</td>
			</tr>
			{% endfor %}
			<tr>
				<td colspan="3" class="text-right"><strong>Total Taxes (Estimate)</strong></td>
				<td class="num"><strong>{{ doc.get_formatted("custom_total_tax") }}</strong></td>
			</tr>
		</tbody>
	</table>
</div>
{% endif %}

{% if doc.items %}
<div class="cgm-section">
	<h3>Local Charges</h3>
	<table class="cgm-grid">
		<thead>
			<tr>
				<th>Description</th>
				<th class="num">Qty</th>
				<th class="num">Rate</th>
				<th class="num">Amount</th>
			</tr>
		</thead>
		<tbody>
			{% for item in doc.items %}
			<tr>
				<td>{{ item.description or item.item_name }}</td>
				<td class="num">{{ item.get_formatted("qty", doc) }}</td>
				<td class="num">{{ item.get_formatted("rate", doc) }}</td>
				<td class="num">{{ item.get_formatted("amount", doc) }}</td>
			</tr>
			{% endfor %}
		</tbody>
	</table>
</div>
{% endif %}

<table class="cgm-totals">
	<tr>
		<td class="label">Sub Total Local Charges:</td>
		<td class="value">{{ doc.get_formatted("total") }}</td>
	</tr>
	{% if doc.custom_total_tax %}
	<tr>
		<td class="label">Total Customs Taxes ({{ company_currency }}):</td>
		<td class="value">{{ doc.get_formatted("custom_total_tax") }}</td>
	</tr>
	{% endif %}
	{% for tax in doc.taxes %}
		{% if tax.tax_amount %}
		<tr>
			<td class="label">{{ tax.description }}:</td>
			<td class="value">{{ tax.get_formatted("tax_amount") }}</td>
		</tr>
		{% endif %}
	{% endfor %}
	<tr>
		<td class="label"><strong>Grand Total:</strong></td>
		<td class="value"><strong>{{ doc.get_formatted("grand_total") }}</strong></td>
	</tr>
</table>

{% if doc.in_words %}
<p><strong>In Words:</strong> {{ doc.in_words }}</p>
{% endif %}

{% if doc.custom_quote_clause or doc.terms %}
<div class="cgm-terms">
	<strong>Remarks / Terms</strong><br>
	{% if doc.custom_quote_clause %}
	<div>{{ doc.custom_quote_clause }}</div>
	{% endif %}
	{% if doc.terms %}
	<div>{{ doc.terms }}</div>
	{% endif %}
</div>
{% endif %}

<div class="cgm-qr">
	<img src="data:image/png;base64,{{ qr }}" alt="Quotation QR Code">
	<div class="caption">Scan to verify quotation {{ doc.name }}</div>
</div>

{% if not no_letterhead and footer %}
<div class="letter-head-footer">{{ footer }}</div>
{% endif %}

</div>
